    <script id="harmat-virtual-unified-sales-20260513">
    (function () {
      function normalize(text) { return String(text || '').toLowerCase().replace(/\s+/g, ' ').trim(); }
      function pageBuilding() {
        var path = normalize(location.pathname);
        var match = path.match(/virtualis-lakasvalaszto-(a[1-4])-epulet/);
        return match ? match[1].toUpperCase() : '';
      }
      function floorLabel(floor) {
        floor = String(floor || '').trim();
        if (!floor || /^f(sz)?$/i.test(floor) || floor === '0') return 'Fsz';
        return floor;
      }
      function floorSort(floor) {
        floor = String(floor || '').trim();
        if (!floor || /^f(sz)?$/i.test(floor) || floor === '0') return 0;
        var n = parseInt(floor, 10);
        return isNaN(n) ? 99 : n;
      }
      function legacyApartment(title) {
        var data = window.LakasparkData && window.LakasparkData.apartments ? window.LakasparkData.apartments : {};
        return data[title] || data[String(title || '').replace(/-/g, '_')] || null;
      }
      function cardFloorText(floor) {
        var label = floorLabel(floor);
        return label === 'Fsz' ? 'Fsz' : label + ' em.';
      }
      function statusLabel(status) {
        status = normalize(status || 'available');
        if (status.indexOf('sold') !== -1 || status.indexOf('elad') !== -1) return 'Eladva';
        if (status.indexOf('reserved') !== -1 || status.indexOf('foglal') !== -1) return 'Foglalva';
        return 'Elérhető';
      }
      function statusClass(status) {
        status = normalize(status || 'available');
        if (status.indexOf('sold') !== -1 || status.indexOf('elad') !== -1) return 'sold';
        if (status.indexOf('reserved') !== -1 || status.indexOf('foglal') !== -1) return 'reserved';
        return 'available';
      }
      function sourceApartments() {
        var list = Array.isArray(window.harmatOfferApartments) ? window.harmatOfferApartments.slice() : [];
        var building = pageBuilding();
        if (building) list = list.filter(function (apt) { return String(apt.building || '').toUpperCase() === building; });
        return list.sort(function (a, b) {
          return String(a.building || '').localeCompare(String(b.building || ''), 'hu') ||
            floorSort(a.floor) - floorSort(b.floor) ||
            String(a.number || a.title || '').localeCompare(String(b.number || b.title || ''), 'hu', { numeric: true });
        });
      }
      function activeRoom() {
        var el = document.getElementById('filterRooms');
        return el ? String(el.value || 'all') : 'all';
      }
      function activeFloor() {
        var active = document.querySelector('.floor-btn.active');
        return active ? String(active.getAttribute('data-val') || 'all') : 'all';
      }
      function matchesFilters(apt) {
        var room = activeRoom();
        var floor = activeFloor();
        var aptFloor = floorLabel(apt.floor).toUpperCase();
        return (room === 'all' || String(apt.rooms) === room) && (floor === 'all' || aptFloor === floor.toUpperCase());
      }
      function cardHtml(apt) {
        var cls = statusClass(apt.status);
        var title = apt.title || [apt.building, apt.floor, apt.number].filter(Boolean).join('-');
        var legacy = legacyApartment(title);
        var img = apt.image || apt.floorplan || (legacy && legacy.image) || '';
        var href = cls === 'sold' ? '#' : (apt.url || apt.link || '#');
        return '<div class="apt-card status-' + cls + '" data-id="' + title + '">' +
          (img ? '<img src="' + img + '" class="apt-card-img" alt="Alaprajz">' : '<div class="apt-card-img">Nincs kép</div>') +
          '<div class="apt-card-content"><div class="apt-card-header"><h3>' + title + '</h3><div class="apt-price">' + statusLabel(apt.status) + '</div></div>' +
          '<div class="apt-meta-grid"><div class="meta-item">' + (apt.rooms || '-') + ' szoba</div><div class="meta-item">' + cardFloorText(apt.floor) + '</div><div class="meta-item">' + (apt.area || apt.b_area || '-') + ' m²</div></div>' +
          '<a href="' + href + '" class="apt-btn-modern">Adatlap</a></div></div>';
      }
      function renderUnifiedList() {
        var container = document.getElementById('apartmentList');
        var count = document.getElementById('resultCount');
        if (!container || !Array.isArray(window.harmatOfferApartments) || !window.harmatOfferApartments.length) return;
        var visible = sourceApartments().filter(matchesFilters);
        container.innerHTML = visible.map(cardHtml).join('');
        if (count) count.textContent = String(visible.length);
      }
      function bindFilters() {
        var rooms = document.getElementById('filterRooms');
        if (rooms && rooms.dataset.harmatUnifiedBound !== '1') {
          rooms.dataset.harmatUnifiedBound = '1';
          rooms.addEventListener('change', function () { setTimeout(renderUnifiedList, 30); });
        }
        document.querySelectorAll('.floor-btn').forEach(function (btn) {
          if (btn.dataset.harmatUnifiedBound === '1') return;
          btn.dataset.harmatUnifiedBound = '1';
          btn.addEventListener('click', function () { setTimeout(renderUnifiedList, 30); });
        });
      }
      function run() { bindFilters(); renderUnifiedList(); }
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run); else run();
      setTimeout(run, 500);
      setTimeout(run, 1200);
      setTimeout(run, 2600);
    })();
    </script>
